    "http://localhost/api/v1/admin/users"
);

const headers = {
    "Authorization": "Bearer {YOUR_JWT_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "name": "Ahmed Khaled",
    "email": "student@example.com",
    "phone": "+201234567890",
    "password": "password123",
    "is_active": true,
    "verification_method": "email",
    "roles": [
        "student"
    ]
};

fetch(url, {
